    functions=["conv_bn_scale_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    Optimized model that fuses Conv2d, BatchNorm, and Scaling into a single custom HIP kernel.
    This reduces memory traffic by avoiding intermediate result storage.
    """
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor):
        super(ModelNew, self).__init__()
        # Store standard layers for parameter initialization
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels)
        self.scaling_factor = scaling_factor
        self.epsilon = 1e-5

        # Get the fused kernel
        self.conv_bn_scale = conv_bn_scale

    def forward(self, x):
        # Use the fused kernel that combines conv + batchnorm + scaling
        return self.conv_bn_scale.conv_bn_scale_hip(
            x,
            self.conv.weight,
            self.conv.bias,
            self.bn.weight,
            self.bn.bias,
            self.bn.running_mean,
            self.bn.running_var,
            self.scaling_factor,
            self.epsilon
        )

