conv_bn_scale_cpp_source = """
#include <hip/hip_runtime.h>

#define TILE_SIZE 16
#define KERNEL_H 3
#define KERNEL_W 3

__global__ void conv_bn_scale_kernel(
    const float* __restrict__ input,      // [N, IC, H, W]
    const float* __restrict__ weight,     // [OC, IC, KH, KW]
    const float* __restrict__ bias,       // [OC]
    const float* __restrict__ bn_weight,  // [OC] - gamma
    const float* __restrict__ bn_bias,    // [OC] - beta
    const float* __restrict__ bn_mean,    // [OC]
    const float* __restrict__ bn_var,     // [OC]
    float* __restrict__ output,           // [N, OC, OH, OW]
    int batch_size,
    int in_channels,
    int out_channels,
    int in_height,
    int in_width,
    int out_height,
    int out_width,
    float scaling_factor,
    float eps) {

    // Shared memory for input tile
    __shared__ float s_input[TILE_SIZE][TILE_SIZE];

    // Compute input tile position
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Output position
    int out_x = bx * TILE_SIZE + tx;
    int out_y = by * TILE_SIZE + ty;

    // Current channel and batch from blockIdx.z and blockIdx.w
    int oc = blockIdx.z % out_channels;
    int n = blockIdx.z / out_channels;

    // Calculate input tile boundaries (need extra for convolution)
    int in_x_start = bx * TILE_SIZE;
    int in_y_start = by * TILE_SIZE;

    // Load input tile into shared memory
    // Each thread loads multiple pixels
    for (int i = ty; i < TILE_SIZE + KERNEL_H - 1; i += TILE_SIZE) {
        for (int j = tx; j < TILE_SIZE + KERNEL_W - 1; j += TILE_SIZE) {
            int in_x = in_x_start + j;
            int in_y = in_y_start + i;

            if (in_x >= 0 && in_x < in_width && in_y >= 0 && in_y < in_height) {
                // Load all channels for this position
                float sum = 0.0f;
                for (int ic = 0; ic < in_channels; ic++) {
                    int input_idx = ((n * in_channels + ic) * in_height + in_y) * in_width + in_x;
                    // Accumulate weighted sum immediately
                    for (int kh = 0; kh < KERNEL_H; kh++) {
                        int ih = in_y - kh;
                        if (ih < 0 || ih >= in_height) continue;

                        for (int kw = 0; kw < KERNEL_W; kw++) {
                            int iw = in_x - kw;
                            if (iw < 0 || iw >= in_width) continue;

                            // Only accumulate when we're at the center of the kernel
                            int weight_idx = ((oc * in_channels + ic) * KERNEL_H + (KERNEL_H - 1 - kh)) * KERNEL_W + (KERNEL_W - 1 - kw);
                            sum += input[input_idx] * weight[weight_idx];
                        }
                    }
                }
                s_input[i % TILE_SIZE][j % TILE_SIZE] = sum;
            } else {
                s_input[i % TILE_SIZE][j % TILE_SIZE] = 0.0f;
            }
        }
    }

    __syncthreads();

    // Write output with BatchNorm and scaling
    if (out_x < out_width && out_y < out_height) {
        int idx = ((n * out_channels + oc) * out_height + out_y) * out_width + out_x;

        float sum = s_input[ty][tx];

        // Add bias
        sum += bias[oc];

        // Apply BatchNorm
        const float mean = bn_mean[oc];
        const float var = bn_var[oc];
        const float inv_std = rsqrtf(var + eps);
        const float normalized = (sum - mean) * inv_std;
        const float bn_out = bn_weight[oc] * normalized + bn_bias[oc];

        // Apply scaling and write
        output[idx] = bn_out * scaling_factor;
    }
}
"""

