conv_bn_scale_opt_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void conv_bn_scale_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    const float* __restrict__ bn_mean,
    const float* __restrict__ bn_var,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_height,
    int in_width,
    int kernel_h,
    int kernel_w,
    int out_height,
    int out_width,
    int stride_h,
    int stride_w,
    int padding_h,
    int padding_w,
    float scaling_factor,
    float eps) {

    // Map blockIdx to batch, output channels, and spatial positions
    int n = blockIdx.x;
    int oc = blockIdx.y;

    // Each thread computes one row of output for this (n, oc)
    int row = threadIdx.x + blockIdx.z * blockDim.x;

    if (row >= out_height) return;

    // Pre-load bias, bn parameters, and gamma/beta
    float b = bias[oc];
    float gamma = bn_weight[oc];
    float beta = bn_bias[oc];
    float mean = bn_mean[oc];
    float var = bn_var[oc];
    float inv_std = rsqrtf(var + eps);
    float scale = gamma * inv_std;
    float offset = beta - gamma * mean * inv_std;

    // Process all columns for this row
    for (int ow = 0; ow < out_width; ow++) {
        float sum = 0.0f;

        // Convolution with tight inner loops
        for (int ic = 0; ic < in_channels; ic++) {
            for (int kh = 0; kh < kernel_h; kh++) {
                int in_h = row * stride_h + kh - padding_h;
                if (in_h < 0 || in_h >= in_height) continue;

                // Pointer to input row
                const float* input_ptr = input + ((n * in_channels + ic) * in_height + in_h) * in_width;
                // Pointer to weight slice
                const float* weight_ptr = weight + ((oc * in_channels + ic) * kernel_h + kh) * kernel_w;

                for (int kw = 0; kw < kernel_w; kw++) {
                    int in_w = ow * stride_w + kw - padding_w;
                    if (in_w >= 0 && in_w < in_width) {
