    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_output = batch_size * out_channels * out_height * out_width;

    if (idx >= total_output) return;

    // Map linear index to (n, oc, oh, ow)
    int n = idx / (out_channels * out_height * out_width);
    int temp = idx % (out_channels * out_height * out_width);
    int oc = temp / (out_height * out_width);
