    int oh = oh_ow / out_width;
    int ow = oh_ow % out_width;

    // Compute convolution for this output position
    float sum = 0.0f;
    int half_kernel = kernel_size / 2;

    for (int ic = 0; ic < in_channels; ic++) {
        for (int kh = 0; kh < kernel_size; kh++) {
