    // Map linear index to (n, oc, oh, ow)
    const int n = idx / (out_channels * out_height * out_width);
    const int temp = idx % (out_channels * out_height * out_width);
    const int oc = temp / (out_height * out_width);
    const int oh_ow = temp % (out_height * out_width);
    const int oh = oh_ow / out_width;
    const int ow = oh_ow % out_width;

    // Compute convolution
    float sum = 0.0f;

    // Loop over input channels and kernel
    for (int ic = 0; ic < in_channels; ic++) {
        for (int kh = 0; kh < kernel_h; kh++) {
            const int in_h = oh * stride_h + kh - padding_h;
            if (in_h < 0 || in_h >= in_height) continue;

            for (int kw = 0; kw < kernel_w; kw++) {
                const int in_w = ow * stride_w + kw - padding_w;
                if (in_w < 0 || in_w >= in_width) continue;

                // Index calculations with proper stride
                // Input: [N, IC, H, W] -> n*IC*H*W + ic*H*W + h*W + w
                const int input_idx = ((n * in_channels + ic) * in_height + in_h) * in_width + in_w;

                // Weight: [OC, IC, KH, KW] -> oc*IC*KH*KW + ic*KH*KW + kh*KW + kw
                const int weight_idx = ((oc * in_channels + ic) * kernel_h + kh) * kernel_w + kw;

                sum += input[input_idx] * weight[weight_idx];
            }
        }
    }

    // Add bias
    sum += bias[oc];

    // Apply BatchNorm: y = gamma * (x - mean) / sqrt(var + eps) + beta
    const float mean = bn_mean[oc];
    const float var = bn_var[oc];
    const float inv_std = rsqrtf(var + eps);
    const float normalized = (sum - mean) * inv_std;
    const float bn_out = bn_weight[oc] * normalized + bn_bias[oc];

    // Apply scaling
    output[idx] = bn_out * scaling_factor;
}

