    float* __restrict__ output,           // [N, OC, OH, OW]
    int batch_size,
    int in_channels,
    int out_channels,
    int in_height,
    int in_width,
    int out_height,
    int out_width,
    float scaling_factor,
    float eps) {

    // Shared memory for input tile
    __shared__ float s_input[TILE_SIZE][TILE_SIZE];

    // Compute input tile position
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Output position
    int out_x = bx * TILE_SIZE + tx;
    int out_y = by * TILE_SIZE + ty;

    // Current channel and batch from blockIdx.z and blockIdx.w
    int oc = blockIdx.z % out_channels;
    int n = blockIdx.z / out_channels;

    // Calculate input tile boundaries (need extra for convolution)
    int in_x_start = bx * TILE_SIZE;
    int in_y_start = by * TILE_SIZE;

    // Load input tile into shared memory
    // Each thread loads multiple pixels
    for (int i = ty; i < TILE_SIZE + KERNEL_H - 1; i += TILE_SIZE) {
        for (int j = tx; j < TILE_SIZE + KERNEL_W - 1; j += TILE_SIZE) {
            int in_x = in_x_start + j;
            int in_y = in_y_start + i;

            if (in_x >= 0 && in_x < in_width && in_y >= 0 && in_y < in_height) {
                // Load all channels for this position
                float sum = 0.0f;
                for (int ic = 0; ic < in_channels; ic++) {
                    int input_idx = ((n * in_channels + ic) * in_height + in_y) * in_width + in_x;
                    // Accumulate weighted sum immediately
                    for (int kh = 0; kh < KERNEL_H; kh++) {
