            } else {
                s_input[i % TILE_SIZE][j % TILE_SIZE] = 0.0f;
            }
        }
    }

    __syncthreads();

    // Write output with BatchNorm and scaling
    if (out_x < out_width && out_y < out_height) {
        int idx = ((n * out_channels + oc) * out_height + out_y) * out_width + out_x;

        float sum = s_input[ty][tx];

        // Add bias
        sum += bias[oc];

        // Apply BatchNorm
        const float mean = bn_mean[oc];
        const float var = bn_var[oc];
        const float inv_std = rsqrtf(var + eps);
        const float normalized = (sum - mean) * inv_std;
        const float bn_out = bn_weight[oc] * normalized + bn_bias[oc];

        // Apply scaling and write
        output[idx] = bn_out * scaling_factor;
    }
